using System.Globalization;
using Avalonia.Data.Converters;

namespace Daqifi.Desktop.Converters;

/// <summary>
/// Multi-value converter that returns <c>true</c> only when every bound value is
/// a <c>true</c> boolean. Used to gate UI on the AND of several conditions — e.g.
/// "the device has a WINC WiFi module" AND "debug mode is enabled".
/// WPF returned Visibility; Avalonia visibility is a bool (IsVisible). Avalonia's
/// IMultiValueConverter has no ConvertBack member (WPF's threw NotSupportedException).
/// </summary>
// @port: Daqifi.Desktop.Converters.BoolAndToVisibilityConverter
public class BoolAndToVisibilityConverter : IMultiValueConverter
{
    /// <summary>
    /// Returns <c>true</c> when every bound value is boolean <c>true</c>.
    /// </summary>
    // @port: Daqifi.Desktop.Converters.BoolAndToVisibilityConverter.Convert
    public object Convert(IList<object?> values, Type targetType, object parameter, CultureInfo culture)
    {
        var allTrue = values != null && values.Count > 0 && values.All(v => v is true);
        return allTrue;
    }
}
